import {Injectable}from'@nestjs/common';import Redis from'ioredis';import {createHash}from'crypto';@Injectable()export class CacheService{private readonly redis=new Redis(process.env.REDIS_URL??'redis://localhost:6379',{lazyConnect:true,maxRetriesPerRequest:1});private readonly ttl=Number(process.env.CACHE_TTL_SECONDS??300);key(input:unknown):string{return'llm:cache:'+createHash('sha256').update(JSON.stringify(input)).digest('hex')}async get<T>(k:string):Promise<T|null>{const v=await this.redis.get(k);return v?JSON.parse(v)as T:null}async set(k:string,v:unknown){await this.redis.set(k,JSON.stringify(v),'EX',this.ttl)}}